package localchat;
import java.nio.file.*;import java.util.*;import java.util.concurrent.atomic.AtomicInteger;
/** Reproduces repeated skill/discovery calls interleaved with genuine document progress. */
public final class SkillProgressTest {
 static int checks;static void check(boolean value,String why){checks++;if(!value)throw new AssertionError(why);}
 static ChatClient.ToolCall call(String name,Map<String,Object> args){return new ChatClient.ToolCall(UUID.randomUUID().toString(),name,args);}
 static Tools.Result read(Tools tools,Path file,int offset,int limit){return tools.execute(call("read_file",Json.obj("path",file.toString(),"offset",offset,"limit",limit)));}
 public static void main(String[] args)throws Exception{
  Path home=Files.createTempDirectory(Files.createDirectories(Path.of(System.getProperty("localchat.home"))),"run-"),dir=Files.createDirectories(home.resolve("skills/demo"));
  Path skill=Files.writeString(dir.resolve("SKILL.md"),"---\nname: demo\ndescription: Fixture\n---\n"+"Long instructions.\n".repeat(600));
  Path procedure=Files.writeString(dir.resolve("PROCEDURA_PROIECTE_MBS.md"),"procedure one\nprocedure two\nprocedure three"),wrong=dir.resolve("references/PROCEDURA_PROIECTE_MBS.md");
  Path project=Files.writeString(home.resolve("PROJECT_INFO.md"),"confirmed project history"),email=Files.writeString(home.resolve("email.txt"),"new email page one\nnew email page two");
  Path secret=Files.writeString(home.resolve("settings.properties"),"PRIVATE-API-SECRET");var asks=new AtomicInteger();
  var loaded=Skills.load(home.resolve("skills"));var tools=new Tools(new Tools.Context(home,home.resolve("skills"),home.resolve("rules.md"),secret,Map.of(),null,new Mcp(),PathMap.none(),false,EnumSet.noneOf(Tools.Access.class),(a,b)->{asks.incrementAndGet();return Tools.Decision.NO;}),loaded);
  String full=Skills.read(loaded,"demo",s->s),index=Skills.resourceIndex(full);
  check(full.indexOf(procedure.toString())<full.indexOf("Long instructions"),"exact resource inventory precedes long skill body");check(index.contains(skill.toString())&&index.contains(procedure.toString())&&!index.contains("Long instructions"),"bounded reminder preserves real paths without procedure reload");
  for(String lang:I18n.CODES){I18n.setLanguage(lang);var result=read(tools,wrong,2,1);check(!result.isError&&result.text.contains(wrong.toString())&&result.text.contains(procedure.toString()),"transparent path correction "+lang);check(result.text.contains("procedure two")&&!result.text.contains("procedure one")&&!result.text.contains("procedure three"),"recovery respects pagination "+lang);}
  I18n.setLanguage("ro");check(asks.get()==0&&!Files.exists(wrong),"owned resource read needs no extra access and creates no alias");check(!read(tools.readOnly(true),wrong,1,1).isError,"recovery works in read-only mode");tools.readOnly(false);
  Files.createDirectories(wrong.getParent());Files.writeString(wrong,"EXACT ORIGINAL");check(read(tools,wrong,1,1).text.contains("EXACT ORIGINAL"),"existing requested path takes precedence");Files.delete(wrong);
  check(read(tools,dir.resolve("references/missing.md"),1,1).isError,"missing root resource is not guessed");check(read(tools,home.resolve("unknown/references/PROCEDURA_PROIECTE_MBS.md"),1,1).isError,"unregistered folder is not redirected");check(read(tools,dir.resolve("references/deeper/PROCEDURA_PROIECTE_MBS.md"),1,1).isError,"only immediate references typo qualifies");
  Path protectedResource=dir.resolve("SECRET.md");Files.createLink(protectedResource,secret);var denied=read(tools,dir.resolve("references/SECRET.md"),1,1);check(denied.isError&&!denied.text.contains("PRIVATE-API-SECRET"),"resource correction cannot bypass secret protection via hard link");Files.delete(protectedResource);
  var guard=new ToolLoopGuard();var repeated=call("read_skill",Json.obj("name","demo"));guard.before(repeated);guard.completed(repeated,Tools.Result.ok(full));for(int i=0;i<8;i++){var result=guard.before(repeated);check(result!=null&&!result.isError&&result.text.contains(procedure.toString()),"reminder retains resource location across real progress");guard.completed(repeated,result);var page=call("read_file",Json.obj("path",email.toString(),"offset",i+1,"limit",1));guard.completed(page,Tools.Result.ok("new page "+i));check(!guard.stalled(repeated),"new page resets no-progress count");}
  for(int i=0;i<5;i++){guard.before(repeated);guard.completed(repeated,Tools.Result.ok(full));guard.completed(call("read_file",Json.obj("path",email.toString(),"offset",8,"limit",1)),Tools.Result.ok("new page 7"));guard.completed(call("read_file",Json.obj("path","missing")),Tools.Result.error("missing"));}check(guard.stalled(repeated),"same page and errors cannot hide a real loop");
  guard.completed(call("edit_file",Json.obj("path",skill.toString())),Tools.Result.ok("changed"));check(guard.before(repeated)==null,"successful edits invalidate skill reminders and allow fresh resource inventory");
  var replies=new ArrayList<FeatureTest.Response>();int n=0;for(var c:List.of(repeated,call("list_dir",Json.obj("path",home.toString())),repeated,call("read_file",Json.obj("path",wrong.toString(),"limit",1)),repeated,call("read_file",Json.obj("path",project.toString())),repeated,call("read_file",Json.obj("path",email.toString(),"offset",1,"limit",1)),repeated,call("read_file",Json.obj("path",email.toString(),"offset",2,"limit",1)),repeated))replies.add(FeatureTest.json(PdfAgentTest.request("r"+(n++),c.name,c.args)));
  replies.add(FeatureTest.json(FeatureTest.answer("ACTUAL FINAL",30,5)));
  try(var server=new FeatureTest.Server(replies.toArray(FeatureTest.Response[]::new))){var agent=new Agent(tools);var results=new ArrayList<Tools.Result>();agent.run(Provider.CUSTOM,server.url(),"","arbitrary-model","fixture","Read assigned procedure and email",List.of(ChatClient.Message.user("Process the new email")),false,new Agent.Ui(){public void text(String s){}public void step(){}public void toolStarted(ChatClient.ToolCall c){}public void toolFinished(ChatClient.ToolCall c,Tools.Result r){results.add(r);}});check(results.size()==11&&results.stream().noneMatch(x->x.isError),"reported skill/document sequence reaches final without false stall");check(agent.collect("","fixture").stream().anyMatch(m->m.content.contains("ACTUAL FINAL")),"actual final response preserved");check(Json.write(server.requests.get(4)).contains("procedure one"),"subsequent model request gets real corrected procedure contents");}
  check(Files.readString(skill).contains("Long instructions")&&Files.readString(procedure).startsWith("procedure one"),"source skill and procedure unchanged");
  System.out.println("PASS: "+checks+" skill resource/progress regression checks; six languages, exact recovery, pagination, protected secrets, real loop and full agent sequence");System.exit(0);
 }
}
